package uk.ac.ravensbourne.casevault;
import static org.junit.jupiter.api.Assertions.assertEquals; import org.flywaydb.core.Flyway; import org.junit.jupiter.api.Test;
class FlywayMigrationTest { @Test void tSchema001MigratesOnPostgresCompatibleH2() throws Exception {var flyway=Flyway.configure().dataSource("jdbc:h2:mem:flyway;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","sa","").locations("classpath:db/migration").load();var dir=java.nio.file.Path.of(getClass().getClassLoader().getResource("db/migration").toURI());long expected;try(var files=java.nio.file.Files.list(dir)){expected=files.filter(p->p.getFileName().toString().matches("V\\d+__.*\\.sql")).count();}assertEquals(expected,flyway.migrate().migrationsExecuted);} }
